sealed interface SaveOutcome {
    data class Saved(val expense: Expense) : SaveOutcome
    data class Invalid(val problems: List<String>) : SaveOutcome
    data class StorageFailure(val cause: Throwable) : SaveOutcome
}

fun saveExpense(store: ExpenseStore, expense: Expense): SaveOutcome =
    try {
        store.save(expense)
        SaveOutcome.Saved(expense)
    } catch (error: java.io.IOException) {
        SaveOutcome.StorageFailure(error)
    }

