sealed interface Outcome {
    data object Saved : Outcome
    data class Failed(val cause: Throwable) : Outcome
}
fun save(write: () -> Unit): Outcome = try {
    write()
    Outcome.Saved
} catch (error: java.io.IOException) {
    Outcome.Failed(error)
}
fun main() {
    println(save { throw java.io.IOException("disk full") } is Outcome.Failed)
